// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ConfirmSignIn Enter the password again, for operations that need a recent sign-in
	// (POST /auth/confirm)
	ConfirmSignIn(w http.ResponseWriter, r *http.Request)
	// Login Sign in with email and password
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout Sign out and end the session
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// GetMe The signed-in adult and their household
	// (GET /auth/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// GetCalendar Events between two household days
	// (GET /calendar)
	GetCalendar(w http.ResponseWriter, r *http.Request, params GetCalendarParams)
	// GetCalendarEvent One event, with its description
	// (GET /calendar/events/{eventId})
	GetCalendarEvent(w http.ResponseWriter, r *http.Request, eventId Id)
	// AssignEventChildren Say which children an event is for
	// (PUT /calendar/events/{eventId}/children)
	AssignEventChildren(w http.ResponseWriter, r *http.Request, eventId Id, params AssignEventChildrenParams)
	// ListCalendars The calendars the household follows
	// (GET /calendars)
	ListCalendars(w http.ResponseWriter, r *http.Request)
	// AddCalendarLink Follow a calendar by its link (ICS or webcal)
	// (POST /calendars)
	AddCalendarLink(w http.ResponseWriter, r *http.Request, params AddCalendarLinkParams)
	// RemoveCalendar Stop following a calendar, with its events and assignments
	// (DELETE /calendars/{calendarId})
	RemoveCalendar(w http.ResponseWriter, r *http.Request, calendarId Id, params RemoveCalendarParams)
	// UpdateCalendar Rename a calendar, recolour it, or show or hide it on displays
	// (PATCH /calendars/{calendarId})
	UpdateCalendar(w http.ResponseWriter, r *http.Request, calendarId Id, params UpdateCalendarParams)
	// ListChildren The children the caller may act for
	// (GET /children)
	ListChildren(w http.ResponseWriter, r *http.Request, params ListChildrenParams)
	// CreateChild Add a child
	// (POST /children)
	CreateChild(w http.ResponseWriter, r *http.Request, params CreateChildParams)
	// GetChild One child
	// (GET /children/{childId})
	GetChild(w http.ResponseWriter, r *http.Request, childId Id)
	// UpdateChild Rename a child, or archive or restore them
	// (PATCH /children/{childId})
	UpdateChild(w http.ResponseWriter, r *http.Request, childId Id, params UpdateChildParams)
	// GetPointsHistory A child's balance and points history, newest first
	// (GET /children/{childId}/history)
	GetPointsHistory(w http.ResponseWriter, r *http.Request, childId Id)
	// RedeemReward Spend points on a reward
	// (POST /children/{childId}/redemptions)
	RedeemReward(w http.ResponseWriter, r *http.Request, childId Id, params RedeemRewardParams)
	// ListChores The household's chores
	// (GET /chores)
	ListChores(w http.ResponseWriter, r *http.Request)
	// CreateChore Add a chore for a child
	// (POST /chores)
	CreateChore(w http.ResponseWriter, r *http.Request, params CreateChoreParams)
	// ArchiveChore Remove a chore from now on (history stays)
	// (DELETE /chores/{choreId})
	ArchiveChore(w http.ResponseWriter, r *http.Request, choreId Id, params ArchiveChoreParams)
	// GetOwnCredential The calling service or assistant credential
	// (GET /credential)
	GetOwnCredential(w http.ResponseWriter, r *http.Request)
	// ListCredentials The household's live service and assistant credentials
	// (GET /credentials)
	ListCredentials(w http.ResponseWriter, r *http.Request)
	// CreateCredential Issue a service or assistant credential
	// (POST /credentials)
	CreateCredential(w http.ResponseWriter, r *http.Request, params CreateCredentialParams)
	// RevokeCredential Revoke a credential; it stops working at once
	// (DELETE /credentials/{credentialId})
	RevokeCredential(w http.ResponseWriter, r *http.Request, credentialId Id, params RevokeCredentialParams)
	// StartDisplayPairing A wall display asks to be paired
	// (POST /display/pairings)
	StartDisplayPairing(w http.ResponseWriter, r *http.Request)
	// ClaimDisplayPairing A wall display collects its session once an adult has entered its code
	// (POST /display/pairings/claim)
	ClaimDisplayPairing(w http.ResponseWriter, r *http.Request, params ClaimDisplayPairingParams)
	// ListDisplays The household's paired wall displays
	// (GET /displays)
	ListDisplays(w http.ResponseWriter, r *http.Request)
	// CreateDisplay Pair the wall display showing this code
	// (POST /displays)
	CreateDisplay(w http.ResponseWriter, r *http.Request, params CreateDisplayParams)
	// RevokeDisplay Unpair a wall display; it stops working at once
	// (DELETE /displays/{displayId})
	RevokeDisplay(w http.ResponseWriter, r *http.Request, displayId Id, params RevokeDisplayParams)
	// GetHousehold The caller's household
	// (GET /household)
	GetHousehold(w http.ResponseWriter, r *http.Request)
	// GetInbox What waits for an adult's decision, oldest first
	// (GET /inbox)
	GetInbox(w http.ResponseWriter, r *http.Request)
	// ApproveInboxItem Say yes; a completion's points land
	// (POST /inbox/{itemId}/approve)
	ApproveInboxItem(w http.ResponseWriter, r *http.Request, itemId ItemId, params ApproveInboxItemParams)
	// RejectInboxItem Send it back, with an optional reason the child sees
	// (POST /inbox/{itemId}/reject)
	RejectInboxItem(w http.ResponseWriter, r *http.Request, itemId ItemId, params RejectInboxItemParams)
	// OpenLive Live updates (WebSocket)
	// (GET /live)
	OpenLive(w http.ResponseWriter, r *http.Request)
	// GetMealWeek The meal plan for the household week containing a date
	// (GET /meals)
	GetMealWeek(w http.ResponseWriter, r *http.Request, params GetMealWeekParams)
	// ClearMeal Clear a planned meal
	// (DELETE /meals/{date}/{slot})
	ClearMeal(w http.ResponseWriter, r *http.Request, date openapi_types.Date, slot MealSlot, params ClearMealParams)
	// SetMeal Plan a meal, or change the planned one
	// (PUT /meals/{date}/{slot})
	SetMeal(w http.ResponseWriter, r *http.Request, date openapi_types.Date, slot MealSlot, params SetMealParams)
	// ReversePoints Take back the points of an award (a chore done by mistake)
	// (POST /points/{entryId}/reverse)
	ReversePoints(w http.ResponseWriter, r *http.Request, entryId Id, params ReversePointsParams)
	// ListRecipes The household's recipes, by title
	// (GET /recipes)
	ListRecipes(w http.ResponseWriter, r *http.Request, params ListRecipesParams)
	// CreateRecipe Add a recipe
	// (POST /recipes)
	CreateRecipe(w http.ResponseWriter, r *http.Request, params CreateRecipeParams)
	// GetRecipe One recipe, to cook from or edit
	// (GET /recipes/{recipeId})
	GetRecipe(w http.ResponseWriter, r *http.Request, recipeId Id)
	// UpdateRecipe Edit a recipe, or archive or restore it
	// (PUT /recipes/{recipeId})
	UpdateRecipe(w http.ResponseWriter, r *http.Request, recipeId Id, params UpdateRecipeParams)
	// ListRewards The rewards children can spend points on
	// (GET /rewards)
	ListRewards(w http.ResponseWriter, r *http.Request)
	// CreateReward Add a reward
	// (POST /rewards)
	CreateReward(w http.ResponseWriter, r *http.Request, params CreateRewardParams)
	// ArchiveReward Remove a reward from now on (history stays)
	// (DELETE /rewards/{rewardId})
	ArchiveReward(w http.ResponseWriter, r *http.Request, rewardId Id, params ArchiveRewardParams)
	// ListRoutines The household's routines
	// (GET /routines)
	ListRoutines(w http.ResponseWriter, r *http.Request)
	// CreateRoutine Add a routine (a list of steps, approved as one) for a child
	// (POST /routines)
	CreateRoutine(w http.ResponseWriter, r *http.Request, params CreateRoutineParams)
	// ArchiveRoutine Remove a routine from now on (history stays)
	// (DELETE /routines/{routineId})
	ArchiveRoutine(w http.ResponseWriter, r *http.Request, routineId Id, params ArchiveRoutineParams)
	// GetToday Today for every child, as the wall display shows it
	// (GET /today)
	GetToday(w http.ResponseWriter, r *http.Request)
	// CompleteChore Mark today's chore done; it waits for an adult's approval
	// (POST /today/chores/{choreId}/complete)
	CompleteChore(w http.ResponseWriter, r *http.Request, choreId Id, params CompleteChoreParams)
	// CheckRoutineStep Tick a step of today's routine; the last one sends the routine for approval
	// (POST /today/routines/{routineId}/steps/{stepId}/check)
	CheckRoutineStep(w http.ResponseWriter, r *http.Request, routineId Id, stepId Id, params CheckRoutineStepParams)
}

