// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ConfirmSignIn Enter the password again, for operations that need a recent sign-in
	// (POST /auth/confirm)
	ConfirmSignIn(ctx context.Context, request ConfirmSignInRequestObject) (ConfirmSignInResponseObject, error)
	// Login Sign in with email and password
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Sign out and end the session
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// GetMe The signed-in adult and their household
	// (GET /auth/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// GetCalendar Events between two household days
	// (GET /calendar)
	GetCalendar(ctx context.Context, request GetCalendarRequestObject) (GetCalendarResponseObject, error)
	// GetCalendarEvent One event, with its description
	// (GET /calendar/events/{eventId})
	GetCalendarEvent(ctx context.Context, request GetCalendarEventRequestObject) (GetCalendarEventResponseObject, error)
	// AssignEventChildren Say which children an event is for
	// (PUT /calendar/events/{eventId}/children)
	AssignEventChildren(ctx context.Context, request AssignEventChildrenRequestObject) (AssignEventChildrenResponseObject, error)
	// ListCalendars The calendars the household follows
	// (GET /calendars)
	ListCalendars(ctx context.Context, request ListCalendarsRequestObject) (ListCalendarsResponseObject, error)
	// AddCalendarLink Follow a calendar by its link (ICS or webcal)
	// (POST /calendars)
	AddCalendarLink(ctx context.Context, request AddCalendarLinkRequestObject) (AddCalendarLinkResponseObject, error)
	// RemoveCalendar Stop following a calendar, with its events and assignments
	// (DELETE /calendars/{calendarId})
	RemoveCalendar(ctx context.Context, request RemoveCalendarRequestObject) (RemoveCalendarResponseObject, error)
	// UpdateCalendar Rename a calendar, recolour it, or show or hide it on displays
	// (PATCH /calendars/{calendarId})
	UpdateCalendar(ctx context.Context, request UpdateCalendarRequestObject) (UpdateCalendarResponseObject, error)
	// ListChildren The children the caller may act for
	// (GET /children)
	ListChildren(ctx context.Context, request ListChildrenRequestObject) (ListChildrenResponseObject, error)
	// CreateChild Add a child
	// (POST /children)
	CreateChild(ctx context.Context, request CreateChildRequestObject) (CreateChildResponseObject, error)
	// GetChild One child
	// (GET /children/{childId})
	GetChild(ctx context.Context, request GetChildRequestObject) (GetChildResponseObject, error)
	// UpdateChild Rename a child, or archive or restore them
	// (PATCH /children/{childId})
	UpdateChild(ctx context.Context, request UpdateChildRequestObject) (UpdateChildResponseObject, error)
	// GetPointsHistory A child's balance and points history, newest first
	// (GET /children/{childId}/history)
	GetPointsHistory(ctx context.Context, request GetPointsHistoryRequestObject) (GetPointsHistoryResponseObject, error)
	// RedeemReward Spend points on a reward
	// (POST /children/{childId}/redemptions)
	RedeemReward(ctx context.Context, request RedeemRewardRequestObject) (RedeemRewardResponseObject, error)
	// ListChores The household's chores
	// (GET /chores)
	ListChores(ctx context.Context, request ListChoresRequestObject) (ListChoresResponseObject, error)
	// CreateChore Add a chore for a child
	// (POST /chores)
	CreateChore(ctx context.Context, request CreateChoreRequestObject) (CreateChoreResponseObject, error)
	// ArchiveChore Remove a chore from now on (history stays)
	// (DELETE /chores/{choreId})
	ArchiveChore(ctx context.Context, request ArchiveChoreRequestObject) (ArchiveChoreResponseObject, error)
	// GetOwnCredential The calling service or assistant credential
	// (GET /credential)
	GetOwnCredential(ctx context.Context, request GetOwnCredentialRequestObject) (GetOwnCredentialResponseObject, error)
	// ListCredentials The household's live service and assistant credentials
	// (GET /credentials)
	ListCredentials(ctx context.Context, request ListCredentialsRequestObject) (ListCredentialsResponseObject, error)
	// CreateCredential Issue a service or assistant credential
	// (POST /credentials)
	CreateCredential(ctx context.Context, request CreateCredentialRequestObject) (CreateCredentialResponseObject, error)
	// RevokeCredential Revoke a credential; it stops working at once
	// (DELETE /credentials/{credentialId})
	RevokeCredential(ctx context.Context, request RevokeCredentialRequestObject) (RevokeCredentialResponseObject, error)
	// StartDisplayPairing A wall display asks to be paired
	// (POST /display/pairings)
	StartDisplayPairing(ctx context.Context, request StartDisplayPairingRequestObject) (StartDisplayPairingResponseObject, error)
	// ClaimDisplayPairing A wall display collects its session once an adult has entered its code
	// (POST /display/pairings/claim)
	ClaimDisplayPairing(ctx context.Context, request ClaimDisplayPairingRequestObject) (ClaimDisplayPairingResponseObject, error)
	// ListDisplays The household's paired wall displays
	// (GET /displays)
	ListDisplays(ctx context.Context, request ListDisplaysRequestObject) (ListDisplaysResponseObject, error)
	// CreateDisplay Pair the wall display showing this code
	// (POST /displays)
	CreateDisplay(ctx context.Context, request CreateDisplayRequestObject) (CreateDisplayResponseObject, error)
	// RevokeDisplay Unpair a wall display; it stops working at once
	// (DELETE /displays/{displayId})
	RevokeDisplay(ctx context.Context, request RevokeDisplayRequestObject) (RevokeDisplayResponseObject, error)
	// GetHousehold The caller's household
	// (GET /household)
	GetHousehold(ctx context.Context, request GetHouseholdRequestObject) (GetHouseholdResponseObject, error)
	// GetInbox What waits for an adult's decision, oldest first
	// (GET /inbox)
	GetInbox(ctx context.Context, request GetInboxRequestObject) (GetInboxResponseObject, error)
	// ApproveInboxItem Say yes; a completion's points land
	// (POST /inbox/{itemId}/approve)
	ApproveInboxItem(ctx context.Context, request ApproveInboxItemRequestObject) (ApproveInboxItemResponseObject, error)
	// RejectInboxItem Send it back, with an optional reason the child sees
	// (POST /inbox/{itemId}/reject)
	RejectInboxItem(ctx context.Context, request RejectInboxItemRequestObject) (RejectInboxItemResponseObject, error)
	// OpenLive Live updates (WebSocket)
	// (GET /live)
	OpenLive(ctx context.Context, request OpenLiveRequestObject) (OpenLiveResponseObject, error)
	// GetMealWeek The meal plan for the household week containing a date
	// (GET /meals)
	GetMealWeek(ctx context.Context, request GetMealWeekRequestObject) (GetMealWeekResponseObject, error)
	// ClearMeal Clear a planned meal
	// (DELETE /meals/{date}/{slot})
	ClearMeal(ctx context.Context, request ClearMealRequestObject) (ClearMealResponseObject, error)
	// SetMeal Plan a meal, or change the planned one
	// (PUT /meals/{date}/{slot})
	SetMeal(ctx context.Context, request SetMealRequestObject) (SetMealResponseObject, error)
	// ReversePoints Take back the points of an award (a chore done by mistake)
	// (POST /points/{entryId}/reverse)
	ReversePoints(ctx context.Context, request ReversePointsRequestObject) (ReversePointsResponseObject, error)
	// ListRecipes The household's recipes, by title
	// (GET /recipes)
	ListRecipes(ctx context.Context, request ListRecipesRequestObject) (ListRecipesResponseObject, error)
	// CreateRecipe Add a recipe
	// (POST /recipes)
	CreateRecipe(ctx context.Context, request CreateRecipeRequestObject) (CreateRecipeResponseObject, error)
	// GetRecipe One recipe, to cook from or edit
	// (GET /recipes/{recipeId})
	GetRecipe(ctx context.Context, request GetRecipeRequestObject) (GetRecipeResponseObject, error)
	// UpdateRecipe Edit a recipe, or archive or restore it
	// (PUT /recipes/{recipeId})
	UpdateRecipe(ctx context.Context, request UpdateRecipeRequestObject) (UpdateRecipeResponseObject, error)
	// ListRewards The rewards children can spend points on
	// (GET /rewards)
	ListRewards(ctx context.Context, request ListRewardsRequestObject) (ListRewardsResponseObject, error)
	// CreateReward Add a reward
	// (POST /rewards)
	CreateReward(ctx context.Context, request CreateRewardRequestObject) (CreateRewardResponseObject, error)
	// ArchiveReward Remove a reward from now on (history stays)
	// (DELETE /rewards/{rewardId})
	ArchiveReward(ctx context.Context, request ArchiveRewardRequestObject) (ArchiveRewardResponseObject, error)
	// ListRoutines The household's routines
	// (GET /routines)
	ListRoutines(ctx context.Context, request ListRoutinesRequestObject) (ListRoutinesResponseObject, error)
	// CreateRoutine Add a routine (a list of steps, approved as one) for a child
	// (POST /routines)
	CreateRoutine(ctx context.Context, request CreateRoutineRequestObject) (CreateRoutineResponseObject, error)
	// ArchiveRoutine Remove a routine from now on (history stays)
	// (DELETE /routines/{routineId})
	ArchiveRoutine(ctx context.Context, request ArchiveRoutineRequestObject) (ArchiveRoutineResponseObject, error)
	// GetToday Today for every child, as the wall display shows it
	// (GET /today)
	GetToday(ctx context.Context, request GetTodayRequestObject) (GetTodayResponseObject, error)
	// CompleteChore Mark today's chore done; it waits for an adult's approval
	// (POST /today/chores/{choreId}/complete)
	CompleteChore(ctx context.Context, request CompleteChoreRequestObject) (CompleteChoreResponseObject, error)
	// CheckRoutineStep Tick a step of today's routine; the last one sends the routine for approval
	// (POST /today/routines/{routineId}/steps/{stepId}/check)
	CheckRoutineStep(ctx context.Context, request CheckRoutineStepRequestObject) (CheckRoutineStepResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// ConfirmSignIn operation middleware
func (sh *strictHandler) ConfirmSignIn(w http.ResponseWriter, r *http.Request) {
	var request ConfirmSignInRequestObject

	var body ConfirmSignInJSONRequestBody
	if err := runtime.BindJSONBody(r, &body); err != nil {
		sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
		return
	}
	request.Body = &body

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.ConfirmSignIn(ctx, request.(ConfirmSignInRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ConfirmSignIn")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(ConfirmSignInResponseObject); ok {
		if err := validResponse.VisitConfirmSignInResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

